-- FASE 2: CREATE CONFIG TABLES
CREATE TABLE INDUSTRIAL_DATA.DOC_TYPE (DOC_TYPE_CODE NVARCHAR(2) NOT NULL PRIMARY KEY, DOC_TYPE_TEXT NVARCHAR(60) NOT NULL);
CREATE TABLE INDUSTRIAL_DATA.PO_STATUS (STATUS_CODE NVARCHAR(10) NOT NULL PRIMARY KEY, STATUS_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA


-- FASE 4: CREATE PURCHASING INFO RECORD (EINA/EINE-style: supplier + material + org + price)
CREATE TABLE INDUSTRIAL_DATA.PURCHASING_INFO_RECORD (
  INFO_RECORD_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  LIFNR NVARCHAR(10) NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  EKORG NVARCHAR(4) NOT NULL,
  NET_PRICE DECIMAL(15, 2) NOT NULL,
  PRICE_UNIT INT NOT NULL,
  INFO_LEAD_TIME_DAYS INT,
  FOREIGN KEY (LIFNR) REFERENCES INDUSTRIAL_DATA.SUPPLIER(LIFNR),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (EKORG) REFERENCES INDUSTRIAL_DATA.PURCHASING_ORGANIZATION(EKORG),
  CHECK (NET_PRICE >= 0),
  CHECK (PRICE_UNIT >= 1)
);

-- FASE 5: CREATE PURCHASE ORDER HEADER + ITEM
CREATE TABLE INDUSTRIAL_DATA.PURCHASE_ORDER (
  EBELN NVARCHAR(10) NOT NULL PRIMARY KEY,
  LIFNR NVARCHAR(10) NOT NULL,
  EKORG NVARCHAR(4) NOT NULL,
  DOC_TYPE_CODE NVARCHAR(2) NOT NULL,
  STATUS_CODE NVARCHAR(10) NOT NULL,
  CURRENCY NVARCHAR(3) NOT NULL,
  PO_DATE DATE NOT NULL,
  ITEM_COUNT INT NOT NULL,
  FOREIGN KEY (LIFNR) REFERENCES INDUSTRIAL_DATA.SUPPLIER(LIFNR),
  FOREIGN KEY (EKORG) REFERENCES INDUSTRIAL_DATA.PURCHASING_ORGANIZATION(EKORG),
  FOREIGN KEY (DOC_TYPE_CODE) REFERENCES INDUSTRIAL_DATA.DOC_TYPE(DOC_TYPE_CODE),
  FOREIGN KEY (STATUS_CODE) REFERENCES INDUSTRIAL_DATA.PO_STATUS(STATUS_CODE),
  FOREIGN KEY (CURRENCY) REFERENCES INDUSTRIAL_DATA.CURRENCY(WAERS),
  CHECK (ITEM_COUNT >= 1)
);

CREATE TABLE INDUSTRIAL_DATA.PURCHASE_ORDER_ITEM (
  PO_ITEM_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  EBELN NVARCHAR(10) NOT NULL,
  ITEM_NO INT NOT NULL,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  QUANTITY DECIMAL(15, 2) NOT NULL,
  NET_PRICE DECIMAL(15, 2) NOT NULL,
  DELIVERY_DATE DATE,
  FOREIGN KEY (EBELN) REFERENCES INDUSTRIAL_DATA.PURCHASE_ORDER(EBELN),
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  CHECK (QUANTITY > 0),
  CHECK (NET_PRICE >= 0)
);

